// v0.4-split: Page drop, combo, and toolbar button setup helpers
// Generated by responsibility split. No functional change intended.



const DEFAULT_APP_INFO = {
  brand: 'FRB Studio',
  product: 'JSON Object Studio',
  version: 'v0.4',
  revision: 'r001',
  display_version: 'v0.4-r001',
  tagline: 'JSONで思考を構造化し、AIとの文脈を育てる。'
};

function normalizeAppInfo(raw) {
  const src = raw && typeof raw === 'object' ? raw : {};
  const info = { ...DEFAULT_APP_INFO, ...src };
  info.brand = String(info.brand || info.app_brand || DEFAULT_APP_INFO.brand).trim();
  info.product = String(info.product || info.name || info.app_name || DEFAULT_APP_INFO.product).trim();
  info.version = String(info.version || DEFAULT_APP_INFO.version).trim();
  info.revision = String(info.revision || DEFAULT_APP_INFO.revision).trim();
  info.display_version = String(
    info.display_version || info.displayVersion || [info.version, info.revision].filter(Boolean).join('-') || DEFAULT_APP_INFO.display_version
  ).trim();
  info.tagline = String(info.tagline || DEFAULT_APP_INFO.tagline).trim();
  return info;
}

function setTextIfExists(id, value) {
  const el = $(id);
  if (el) el.textContent = value ?? '';
}

function applyAppInfo(raw) {
  currentAppInfo = normalizeAppInfo(raw);
  setTextIfExists('appBrand', currentAppInfo.brand);
  setTextIfExists('appProductName', currentAppInfo.product);
  setTextIfExists('appDisplayVersion', currentAppInfo.display_version);
  setTextIfExists('appTagline', currentAppInfo.tagline);
  document.title = `${currentAppInfo.brand} - ${currentAppInfo.product} ${currentAppInfo.display_version}`.trim();
  document.body.dataset.appBrand = currentAppInfo.brand;
  document.body.dataset.appProduct = currentAppInfo.product;
  return currentAppInfo;
}

async function loadAndApplyAppInfo() {
  try {
    const res = await fetch('config/app_info.json', { cache: 'no-store' });
    if (!res.ok) throw new Error(`config/app_info.json (${res.status})`);
    return applyAppInfo(await res.json());
  } catch (err) {
    console.warn('app_info.json を読み込めなかったため既定表示を使います', err);
    return applyAppInfo(DEFAULT_APP_INFO);
  }
}

function suppressBrowserAutofillOnComboInputs() {
  [
    { id: 'defNameInput', name: 'frb_def_combo_009' },
    { id: 'dataNameInput', name: 'frb_data_combo_009' }
  ].forEach(({ id, name }) => {
    const input = $(id);
    if (!input) return;
    input.setAttribute('autocomplete', 'off');
    input.setAttribute('autocorrect', 'off');
    input.setAttribute('autocapitalize', 'off');
    input.setAttribute('spellcheck', 'false');
    input.setAttribute('inputmode', 'latin');
    input.setAttribute('enterkeyhint', 'search');
    input.setAttribute('data-studio-ime-policy', 'latin-filename');
    // Browser IME制御は完全強制できないが、Windows/旧Edge系も含めて可能な範囲で英数字入力を促す。
    input.style.imeMode = 'inactive';
    input.setAttribute('name', name);
  });
}

function setupPageDrop() {
  document.querySelectorAll('.drop-file-box').forEach(setupDropFileBox);
  document.addEventListener('dragover', (e) => e.preventDefault());
  document.addEventListener('drop', (e) => e.preventDefault());
}


function hasViewDefMarkdownTarget() {
  const droppedDefFile = $('defFile')?.files?.[0] ?? null;
  const comboName = safeJsonFileName($('defNameInput')?.value);
  const loadedName = safeJsonFileName(lastLoadedDefName);
  return Boolean(viewDef || droppedDefFile || comboName || loadedName);
}

function updateViewDefMarkdownButtonState() {
  const btn = $('exportViewDefMarkdownBtn');
  if (btn) btn.disabled = !hasViewDefMarkdownTarget();
  if (typeof updateViewDefMaintenanceButtonState === 'function') updateViewDefMaintenanceButtonState();
}

function setupViewDefMarkdownButtonState() {
  const defInput = $('defNameInput');
  const defFile = $('defFile');
  if (defInput) {
    defInput.addEventListener('input', updateViewDefMarkdownButtonState);
    defInput.addEventListener('change', updateViewDefMarkdownButtonState);
  }
  if (defFile) defFile.addEventListener('change', updateViewDefMarkdownButtonState);
  updateViewDefMarkdownButtonState();
}


const VIEWDEF_MAINTENANCE_VIEWDEF_PATH = 'common/view_def_maint_fields_v0_2.json';

function selectedViewDefForMaintenance() {
  return safeJsonFileName($('defNameInput')?.value) || safeJsonFileName(lastLoadedDefName);
}

function updateViewDefMaintenanceButtonState() {
  const btn = $('maintainViewDefBtn');
  if (!btn) return;
  const selected = selectedViewDefForMaintenance();
  btn.disabled = !selected || selected === VIEWDEF_MAINTENANCE_VIEWDEF_PATH;
}

async function openSelectedViewDefForMaintenance() {
  const targetName = selectedViewDefForMaintenance();
  if (!targetName) {
    setStatus('メンテナンスするViewDefが選択されていません', { kind: 'warn', title: 'ViewDef未選択' });
    return false;
  }
  if (targetName === VIEWDEF_MAINTENANCE_VIEWDEF_PATH) {
    setStatus('ViewDefメンテ用ViewDef自身は「…」から再帰的には開きません', { kind: 'warn', title: '自己参照抑止' });
    return false;
  }

  const [maintenance, target] = await Promise.all([
    fetchApiJsonWithUrl('defs', VIEWDEF_MAINTENANCE_VIEWDEF_PATH),
    fetchApiJsonWithUrl('defs', targetName)
  ]);
  if (target?.readonly) {
    throw new Error(`Overlay等の読取専用ViewDefはこの導線では上書きできません: ${targetName}`);
  }

  lastLoadedDefName = VIEWDEF_MAINTENANCE_VIEWDEF_PATH;
  currentViewDefMaintenanceTarget = targetName;
  if ($('defNameInput')) $('defNameInput').value = VIEWDEF_MAINTENANCE_VIEWDEF_PATH;
  if ($('dataNameInput')) $('dataNameInput').value = '';
  if ($('defFile')) $('defFile').value = '';
  if ($('dataFile')) $('dataFile').value = '';

  const writableUrl = String(target?.url ?? '').startsWith('/api/defs/') ? target.url : null;
  const maintenanceData = (typeof buildViewDefMaintenanceDocument === 'function')
    ? buildViewDefMaintenanceDocument(target.json)
    : target.json;
  const maintenanceViewDef = (typeof configureViewDefMaintenanceViewDef === 'function')
    ? configureViewDefMaintenanceViewDef(maintenance.json, target.json)
    : maintenance.json;
  const maintenanceSectionCatalog = (typeof viewDefMaintenanceSectionCatalog === 'function')
    ? viewDefMaintenanceSectionCatalog(target.json)
    : [];
  const maintenanceDefaultSectionRef = (typeof viewDefMaintenancePreferredDefaultSectionRef === 'function')
    ? viewDefMaintenancePreferredDefaultSectionRef(maintenanceSectionCatalog)
    : '';
  await loadFromObjects(
    maintenanceViewDef,
    maintenanceData,
    `ViewDefメンテナンス: ${targetName}`,
    writableUrl,
    `ViewDef: ${targetName}`,
    'viewdef'
  );
  // v0.18.56:
  // ViewDef全Sectionを編集可能な構造は維持するが、初期表示で全部を混ぜない。
  // 通常画面の主一覧に対応する first main grid section を自動選択し、
  // 「…」を押した直後から現在画面のcaptionと対応するFieldだけを見せる。
  if (maintenanceDefaultSectionRef && typeof applyStudioSearchState === 'function') {
    applyStudioSearchState({
      core: { __maintenance_section_ref: maintenanceDefaultSectionRef }
    }, { runSearch: true });
  }
  currentViewDefMaintenanceTarget = targetName;
  updateViewDefMaintenanceButtonState();
  if (typeof updateSelectedJsonFolderButtonStates === 'function') updateSelectedJsonFolderButtonStates();
  console.log(`[FRBStudio ViewDef maintenance] ${targetName} を ${VIEWDEF_MAINTENANCE_VIEWDEF_PATH} で開きました`);
  return true;
}

function setupViewDefMaintenanceButton() {
  const btn = $('maintainViewDefBtn');
  const input = $('defNameInput');
  if (!btn || !input) return;

  const moveUp = $('viewDefMoveUpBtn');
  const moveDown = $('viewDefMoveDownBtn');
  if (moveUp && moveUp.dataset.viewdefOrderInstalled !== '1') {
    moveUp.dataset.viewdefOrderInstalled = '1';
    moveUp.addEventListener('click', () => moveSelectedViewDefMaintenanceRow(-1));
  }
  if (moveDown && moveDown.dataset.viewdefOrderInstalled !== '1') {
    moveDown.dataset.viewdefOrderInstalled = '1';
    moveDown.addEventListener('click', () => moveSelectedViewDefMaintenanceRow(1));
  }
  if (btn.dataset.viewdefMaintenanceInstalled === '1') {
    updateViewDefMaintenanceButtonState();
    return;
  }
  btn.dataset.viewdefMaintenanceInstalled = '1';
  input.addEventListener('input', updateViewDefMaintenanceButtonState);
  input.addEventListener('change', updateViewDefMaintenanceButtonState);
  btn.addEventListener('click', async (event) => {
    event.preventDefault();
    event.stopPropagation();
    try {
      await openSelectedViewDefForMaintenance();
    } catch (err) {
      console.error(err);
      setStatus(`ViewDefメンテナンスを開始できません: ${err.message}`, { kind: 'error', title: 'ViewDefメンテナンス' });
    }
  });
  updateViewDefMaintenanceButtonState();
}

function setupComboClearButtons() {
  const configs = [
    { inputId: 'defNameInput', buttonId: 'clearDefNameBtn', label: '画面定義JSON', names: () => (typeof viewDefSelectionNames === 'function' ? viewDefSelectionNames() : serverDefNames) },
    { inputId: 'dataNameInput', buttonId: 'clearDataNameBtn', label: '対象JSON', names: () => serverDataNames }
  ];
  configs.forEach(({ inputId, buttonId, label, names }) => {
    const input = $(inputId);
    const button = $(buttonId);
    if (!input || !button) return;

    const sync = () => {
      button.classList.toggle('visible', String(input.value ?? '').trim().length > 0);
    };

    input.addEventListener('input', sync);
    input.addEventListener('change', () => {
      try {
        normalizeComboInput(input, names(), label);
      } catch (err) {
        console.warn(err);
        setStatus('選択エラー: ' + err.message, { kind: 'error', title: '選択エラー' });
      }
      sync();
    });
    button.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      input.value = '';
      input.dispatchEvent(new Event('input', { bubbles: true }));
      updateViewDefMarkdownButtonState();
      input.focus();
      console.log(`[FRBStudio combo] ${label}の選択をクリアしました`);
    });
    sync();
  });
}

async function readJsonFile(input) {
  const file = input.files?.[0];
  if (!file) throw new Error('ファイルが選択されていません');
  const text = await file.text();
  return JSON.parse(text);
}
